const Room=require("../models/roomModel"),User=require("../models/userModel"),handleErrors=require("../utilities/handle_errors")["handleErrors"],create_room=(e,t,o)=>{var r={players:[e.body.userId]};Room.create(r).then(o=>{User.findById({_id:e.body.userId}),t.status(200).send(o)}).catch(o=>{t.status(422).send(handleErrors(o,e,"room"))})},get_rooms=(o,t,r)=>{const s=o.query.page-1||0;Room.find({}).count().then(e=>{Room.find({}).sort({createdAt:-1}).skip(8*s).limit(8).then(o=>t.status(200).send({rooms:o,total_rooms:e,per_page:8})).catch(r)})},get_admin_rooms=(o,t,r)=>{const s=o.query.page-1||0;Room.find({}).count().then(e=>{Room.find({}).skip(30*s).limit(30).then(o=>t.status(200).send({rooms:o,total_rooms:e,per_page:30})).catch(r)})},get_single_room=(o,e,t)=>{Room.findById({_id:o.params.id}).then(o=>e.status(200).send(o)).catch(t)},update_room=(e,t,o)=>{Room.findByIdAndUpdate({_id:e.params.id},e.body).then(o=>{Room.findOne({_id:e.params.id}).then(o=>t.status(200).send(o))}).catch(o)},delete_room=(o,e,t)=>{Room.findByIdAndDelete({_id:o.params.id}).then(o=>{e.status(200).send(o)}).catch(t)};module.exports={create_room:create_room,update_room:update_room,get_single_room:get_single_room,get_admin_rooms:get_admin_rooms,get_rooms:get_rooms,delete_room:delete_room};